import { createMemo, createRoot, createSignal } from "solid-js";
import { redirect } from "@solidjs/router";

export type CartItem = {
  id: string;
  name: string;
  price: number;
  quantity: number;
};

function createCartStore() {
  const [items, setItems] = createSignal<CartItem[]>([]);

  const total = createMemo(function sum() {
    return items().reduce(function addToTotal(value, item) {
      return value + item.price * item.quantity;
    }, 0);
  });

  function add(item: CartItem) {
    setItems(function append(current) {
      return [...current, item];
    });
  }

  return { items, total, add };
}

export const cart = createRoot(createCartStore);

export function requireCart() {
  if (cart.items().length === 0) {
    throw redirect("/catalog");
  }
}
